function safeFileBase(p){ return p.split('/').pop(); }
try { require('fs').mkdirSync('/tmp/praxis-signals', { recursive: true }); } catch (e) {}
const items = $input.all();
const results = [];
for (const it of items) {
  const body = (it.json && it.json.body) ? it.json.body : it.json;
  const errs = [];
  const required = ['symbol','side','qty','price','signal_id','ts'];
  for (const k of required) { if (body[k] === undefined || body[k] === null || body[k] === '') errs.push('missing ' + k); }
  if (body.side && !['BUY','SELL'].includes(String(body.side).toUpperCase())) errs.push('side must be BUY or SELL');
  const qtyNum = Number(body.qty);
  if (!Number.isFinite(qtyNum) || qtyNum <= 0) errs.push('qty must be number > 0');
  const priceNum = Number(body.price);
  if (!Number.isFinite(priceNum)) errs.push('price must be number');
  if (body.ts && isNaN(Date.parse(body.ts))) errs.push('ts must be ISO timestamp');
  const valid = errs.length === 0;
  let fileName = '';
  let payloadJson = '';
  if (valid) {
    const safeTs = String(body.ts).replace(/:/g, '-');
    const safeId = String(body.signal_id).replace(/[^a-zA-Z0-9_.-]/g, '_');
    fileName = '/tmp/praxis-signals/' + safeTs + '-' + safeId + '.json';
    payloadJson = JSON.stringify(body, null, 2);
  }
  const json = { valid, error: errs.join('; '), fileName, body };
  if (valid) {
    const buf = Buffer.from(payloadJson, 'utf-8');
    results.push({ json, binary: { data: { data: buf.toString('base64'), mimeType: 'application/json', fileName: safeFileBase(fileName), fileExtension: 'json' } } });
  } else {
    results.push({ json });
  }
}
return results;

const fs = require('fs');
fs.mkdirSync('/tmp/praxis-signals', { recursive: true });
const results = [];
for (const it of $input.all()) {
  fs.writeFileSync(it.json.fileName, JSON.stringify(it.json.body, null, 2), 'utf-8');
  results.push({ json: it.json });
}
return results;
